import fs from 'node:fs';
import assert from 'node:assert/strict';
import { privateDecrypt, constants, randomUUID } from 'node:crypto';
import { setTimeout as delay } from 'node:timers/promises';
import { setGlobalProxyFromEnv } from 'node:http';
import { query, decode } from '../../test/helpers/dns-wire.mjs';
process.env.HTTP_PROXY=process.env.HTTPS_PROXY='http://127.0.0.1:7889';setGlobalProxyFromEnv();
const dir=import.meta.dirname, phase=Number(process.argv[2]);
const transcript=fs.readFileSync(process.env.DNS_DIAGNOSTIC_TRANSCRIPT,'utf8');
const phases=new Map();
function scan(v){if(typeof v==='string'){try{const j=JSON.parse(v);if(j.kind==='closeout-key-phase')phases.set(j.phase,j);}catch{}}else if(Array.isArray(v))v.forEach(scan);else if(v&&typeof v==='object')Object.values(v).forEach(scan);}
for(const l of transcript.trim().split('\n'))try{scan(JSON.parse(l));}catch{}
const key=n=>privateDecrypt({key:fs.readFileSync(dir+'/private.pem'),padding:constants.RSA_PKCS1_OAEP_PADDING,oaepHash:'sha256'},Buffer.from(phases.get(n).encryptedKey,'base64')).toString();
const resume=process.argv.includes('--resume'),current=key(phase), old=phase===2?key(1):undefined, wire=query('example.com',1);
const file=dir+'/key-ledger.json',ledger=fs.existsSync(file)?JSON.parse(fs.readFileSync(file)):{cap:24,samples:[]};
const save=()=>fs.writeFileSync(file,JSON.stringify(ledger,null,2));
async function request(label,path,status,{method='POST',json=false}={}){
 assert.ok(ledger.samples.length<24);if(ledger.lastCompletedAt)await delay(Math.max(0,1050-(Date.now()-ledger.lastCompletedAt)));
 const row={id:randomUUID(),phase,label,startedAt:new Date().toISOString(),correct:false,expectedStatus:status};ledger.samples.push(row);save();
 try{const r=await fetch('https://superdoh.aloneowo0.workers.dev'+path,{method,headers:{'Content-Type':'application/dns-message','Accept':json?'application/dns-json':'application/dns-message'},...(method==='POST'?{body:wire}:{}),redirect:'manual',signal:AbortSignal.timeout(15000)});row.status=r.status;const bytes=Buffer.from(await r.arrayBuffer());assert.ok(bytes.length<65536);assert.equal(r.status,status);
 if(status===200){assert.equal(r.headers.get('cache-control'),'no-store');if(json){const d=JSON.parse(bytes);assert.equal(d.Status,0);assert.equal(d.Answer.length,1);assert.equal(d.Answer[0].data,phase===1?'192.0.2.8':'192.0.2.9');assert.equal(d.Answer[0].TTL,60);}else{const d=decode(bytes);assert.equal(d.id,0x4242);assert.equal(d.flags&15,0);assert.equal(d.flags&32,0);assert.deepEqual(d.questions,[{name:'example.com',type:1,class:1}]);const a=d.records.filter(x=>x.section===0);assert.equal(a.length,1);assert.equal(a[0].ttl,60);assert.deepEqual(a[0].data,[192,0,2,phase===1?8:9]);}}
 row.correct=true;
 }catch{row.errorCode='CLOUD_ASSERTION_OR_TRANSPORT_FAILED';process.exitCode=1;}
 finally{row.finishedAt=new Date().toISOString();ledger.lastCompletedAt=Date.now();save();}
 assert.ok(row.correct,'Cloud check failed: '+label);
}
try{
 if(phase===1&&!resume){await request('missing-key','/dns-query',404);await request('wrong-key','/invalid-key/dns-query',404);await request('unauthorized-malformed-json','/dns-query?name=x&name=y',404,{method:'GET',json:true});}
 else if(phase===2)await request('retired-key','/'+old+'/dns-query',404);
 if(!resume)await request('authorized-wire-post','/'+current+'/dns-query',200);
 await request('authorized-wire-get','/'+current+'/dns-query?dns='+Buffer.from(wire).toString('base64url'),200,{method:'GET'});
 await request('authorized-json-get','/'+current+'/dns-query?name=example.com&type=A',200,{method:'GET',json:true});
 if(phase===1)await request('authorized-invalid-json','/'+current+'/dns-query?name=x&name=y',400,{method:'GET',json:true});
 console.log(JSON.stringify({phase,correct:ledger.samples.filter(x=>x.correct).length,total:ledger.samples.length}));
}catch{console.error(JSON.stringify({error:'BOUNDED_KEY_CHECK_FAILED',phase,total:ledger.samples.length}));process.exitCode=1;}
